commits.content:
const Hangman = ({ errorsCount }) => {
  return (
    <div className="hangman">
      <div className="hangman__gallows"></div>
      <div
        className={`hangman__head ${errorsCount > 0 ? "visible" : ""}`}
      ></div>
      <div
        className={`hangman__body ${errorsCount > 1 ? "visible" : ""}`}
      ></div>
      <div
        className={`hangman__left-arm ${errorsCount > 2 ? "visible" : ""}`}
      ></div>
      <div
        className={`hangman__right-arm ${errorsCount > 3 ? "visible" : ""}`}
      ></div>
      <div
        className={`hangman__left-leg ${errorsCount > 4 ? "visible" : ""}`}
      ></div>
      <div
        className={`hangman__right-leg ${errorsCount > 5 ? "visible" : ""}`}
      ></div>
    </div>
  );
};

export default Hangman;
